{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "LY2196044, which contains an aromatic primary carboxamide and a basic secondary amine, had an absolute oral bioavailability of 45% in humans, supporting high F for the query's similar amide/amine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "5-HT3 antagonists with basic amine and amide/aromatic heterocycle structures are well absorbed orally with bioavailability of 50–80%, supporting high F for a basic amine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ketanserin, a basic piperidine-containing drug, showed absolute oral bioavailability of about 50% in healthy subjects, supporting high F for the query's basic amine feature.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Bopindolol, an indole-containing basic amine drug, had absolute bioavailability of about 70% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Indacaterol, an indole-containing amine, had oral bioavailability of approximately 24% in humans, just above the 20% threshold, providing weak supportive evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Mebendazole had an absolute bioavailability of about 1% in humans, but its benzimidazole carbamate structure lacks the basic amine and has poor solubility, making this low-F evidence weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rebamipide had bioavailability under 10% in humans, but its carboxylic acid and zwitterionic character are not shared by the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on multiple human oral bioavailability measurements in analogues sharing basic amine and primary amide/aromatic amide features; low-F analogues are structurally dissimilar (carbamate/acid) and less transferable.",
  "evidence_gaps": [
    "No experimental bioavailability data for the exact query scaffold; all analogues have low Morgan similarity (<0.25).",
    "No direct measurements of solubility, permeability, or first-pass metabolism for the query.",
    "Human F data for the closest primary-amide/basic-amine analogue (LY2196044) is from a single clinical estimate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

